// The roles table.
// Generated by tylix make:permissions. Yours to edit.
//
// Read roles with it; change them through `permissions` (app/permissions),
// which keeps grants, inheritance and the cache in step:
//   await permissions.createRole('support', { permissions: ['users.view'] })
import { Model } from '@tylix/orm'
import { permissions } from '../permissions.js'

export class Role extends Model {
  static table = 'roles'
  static fillable = ['name', 'description']

  static async findByName(name: string) {
    return this.where('name', name).first()
  }

  // The role with its grants and the roles it inherits.
  static async details(name: string) {
    return permissions.findRole(name)
  }

  // Users who were given this role (inherited roles aren't listed).
  static async users(name: string) {
    return permissions.subjectsWithRole(name)
  }
}
